styles:
.page-case .case-hero { padding-top: clamp(140px, 18vh, 220px); padding-bottom: clamp(30px, 5vw, 60px); }
.page-case .case-hero__eyebrow { display: flex; flex-wrap: wrap; gap: 10px 14px; margin-bottom: clamp(18px, 3vw, 32px); }
.page-case .case-tag { font-size: clamp(13px, 1vw, 15px); color: var(--red); border: 1px solid var(--line); border-radius: 999px; padding: 6px 16px; }
.page-case .case-hero__title { font-size: clamp(52px, 10vw, 150px); color: var(--grey-700); letter-spacing: -0.01em; line-height: 1; }
.page-case .case-hero__lede { font-family: var(--font-display); font-size: clamp(20px, 2.1vw, 32px); color: var(--grey-700); margin-top: clamp(16px, 2vw, 26px); max-width: 26ch; line-height: 1.15; }
.page-case .case-meta { display: flex; flex-wrap: wrap; gap: 10px 26px; margin-top: clamp(24px, 3vw, 40px); font-size: clamp(15px, 1.1vw, 18px); color: var(--grey-500); }
.page-case .case-meta strong { font-family: var(--font-display); color: var(--grey-900); font-weight: 400; margin-right: 8px; }

.page-case .case-cover { border-radius: var(--radius-lg); overflow: hidden; background: var(--bg-alt); margin-top: clamp(20px, 3vw, 40px); }
.page-case .case-cover img { width: 100%; height: auto; }

.page-case .creators { display: grid; grid-template-columns: repeat(4, 1fr); gap: clamp(16px, 2vw, 28px); margin-top: clamp(36px, 5vw, 64px); }
.page-case .creator { border: 1px solid var(--line); border-radius: var(--radius); padding: clamp(18px, 1.8vw, 26px); }
.page-case .creator__name { font-family: var(--font-display); font-size: clamp(20px, 1.8vw, 26px); color: var(--grey-900); }
.page-case .creator__role { font-size: clamp(14px, 1vw, 16px); color: var(--grey-500); margin-top: 4px; }

.page-case .prose { max-width: 62ch; }
.page-case .prose h2 { font-size: clamp(30px, 3.6vw, 52px); color: var(--red); line-height: 1.05; margin-bottom: clamp(16px, 1.6vw, 24px); }
.page-case .prose p { color: var(--grey-700); font-size: clamp(16px, 1.15vw, 19px); }
.page-case .prose p + p { margin-top: 16px; }
.page-case .prose ol { margin: 16px 0 0 1.1em; color: var(--grey-700); font-size: clamp(16px, 1.15vw, 19px); }
.page-case .prose ol li { margin-bottom: 10px; padding-left: 6px; }
.page-case .prose ol li::marker { color: var(--red); font-family: var(--font-display); }

.page-case .case-figure { border-radius: var(--radius-lg); overflow: hidden; background: var(--bg-alt); margin-top: clamp(28px, 4vw, 56px); }
.page-case .case-figure img { width: 100%; height: auto; }
.page-case .case-figure--pad { padding: clamp(20px, 4vw, 64px); }

.page-case .case-split { display: grid; grid-template-columns: 1fr 1fr; gap: clamp(28px, 4vw, 72px); align-items: center; }
.page-case .case-split .case-figure { margin-top: 0; }

.page-case .back-link { display: inline-flex; align-items: center; gap: 12px; font-family: var(--font-display); font-size: clamp(18px, 1.6vw, 24px); color: var(--grey-900); border: 1px solid var(--grey-300); border-radius: 999px; padding: 12px 14px 12px 26px; transition: border-color .3s var(--ease), color .3s var(--ease); }
.page-case .back-link .arrow { width: 34px; height: 34px; border-radius: 50%; border: 1.5px solid var(--red); color: var(--red); display: grid; place-items: center; transition: transform .3s var(--ease), background .3s var(--ease), color .3s var(--ease); }
.page-case .back-link:hover { border-color: var(--red); color: var(--red); }
.page-case .back-link:hover .arrow { background: var(--red); color: #fff; transform: translateX(2px); }

@media (max-width: 1024px) {
  .page-case .creators { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 760px) {
  .page-case .creators { grid-template-columns: 1fr; }
  .page-case .case-split { grid-template-columns: 1fr; }
}
